head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.vSecugrpID = SECUGRP_ID_BC;
scwin.vMktId = $c.lc.fn_getMktId();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.listSync2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05630.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05630.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05630.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ListChgHist_OnLoadCompleted
 * @description dts_ListChgHist 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ListChgHist_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page3);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05630.dts_ListChgHist_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_ISU_NM_onclick
 * @description img_ISU_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_NM_onclick = function() {
    try {
        $c.lc.fn_PopFindIsu(SECUGRP_ID_BC);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05630.img_ISU_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISU_NM.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
        } else {
            await scwin.openDetail(-999);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05630.btn_New_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        await scwin.openDetail(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05630.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_ISU_NM.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
            txb_ISU_NM.focus();
        } else {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05630.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_srchChgHist_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_srchChgHist_onclick = async function() {
    try {
        await scwin.listSync2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05630.btn_srchChgHist_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            $c.stf.doLogSave("ULDSTF05630.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_List, {fileName: $c.lc.fn_getSecuGrpNm(scwin.vSecugrpID) + " 존립기간변경목록", type: "8"});
        }
        if (dts_ListChgHist.getRowCount() > 0) {
            $c.stf.doLogSave("ULDSTF05630.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_ListChgHist, {fileName: $c.lc.fn_getSecuGrpNm(scwin.vSecugrpID) + " 신탁기간 만료일 정정사항", type: "8"});
        }
        if (dts_List.getRowCount() === 0 && dts_ListChgHist.getRowCount() === 0) {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05630.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05630.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_MKTACT_ENFORCE_DD_onclick
 * @description img_MKTACT_ENFORCE_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    try {
        popUpCalendar2(edt_MKTACT_ENFORCE_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05630.img_MKTACT_ENFORCE_DD_onclick" });
    }
};

/**
 * @method
 * @name img_MKTACT_ENFORCE_DD_onclick
 * @description img_MKTACT_ENFORCE_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    try {
        popUpCalendar2(edt_MKTACT_ENFORCE_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05630.img_MKTACT_ENFORCE_DD_onclick" });
    }
};

/**
 * @method
 * @name grd_ListChgHist_OnDblClick
 * @description grd_ListChgHist 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_ListChgHist_OnDblClick = function(row, colid) {
    try {
        txb_ISU_CD.setValue(dts_ListChgHist.getCellData(row, "ISU_CD"));
        txb_ISU_NM.setValue(dts_ListChgHist.getCellData(row, "ISU_KOR_NM"));
        scwin.vIsurCd = dts_ListChgHist.getCellData(row, "ISUR_CD");
        btn_Search.trigger("onclick");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05630.grd_ListChgHist_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05630.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=exstlistMarketBC&inputMessageId=FISCYY_CHG_INOUT&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/fiscalYearChange.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync2
 * @description list Sync2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync2 = async function() {
    url += "?SCREN_ID=" + "ULDSTF05630.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=FISCYY_CHG_LIST_ISU_BC" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.existencebc.select.updateall" + "&{P}param01=" + edt_MKTACT_ENFORCE_DD.getValue() + "&{P}param02=" + edt_MKTACT_ENFORCE_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_ListChgHist",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ListChgHist=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getPar
 * @description get Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    arrPar[0] = txb_ISU_CD.getValue();
    arrPar[1] = txb_ISU_NM.getValue();
    arrPar[2] = scwin.vSecugrpID;
    arrPar[3] = scwin.vMktId;
    arrPar[4] = scwin.vBzProcsNo;
    arrPar[5] = scwin.vIsurCd;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        btn_Search.trigger("onclick");
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    if (row > 0) {
        scwin.setBzProcsNo(row);
    } else {
        scwin.vBzProcsNo = "";
    }
    const options = {
        id: "ULDSTF05631",
        title: $c.lc.fn_getSecuGrpNm(scwin.vSecugrpID) + " 존립기간 변경관리",
        type: "pageFramePopup",
        width: 665 + 2,
        height: "360px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정
    };

    const result = await $c.win.openPopup("/lstproc/ULDSTF05631.gfm", options, data);
    // TO-DO : result 값 확인 후 업무 로직 추가
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.vBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
};
